describe("extraUnsealPasswords", () => {
  const previousPassword = "previous-password-that-is-long-enough";
  const strangerPassword = "stranger-password-that-is-long-enough";
  const createdAt = Date.parse("2029-06-01T00:00:00Z");
  const legacySealOptions = {
    ...sealDefaults,
    encryption: { ...sealDefaults.encryption, iterations: 1 },
    integrity: { ...sealDefaults.integrity, iterations: 1 },
  };
  const extraConfig: SessionConfig = {
    ...sessionConfig,
    extraUnsealPasswords: [previousPassword],
  };
  const sealedWith = (password: string, data: object, options = sealDefaults) =>
    seal({ id: "old", createdAt, data }, password, options);
  const resealedCookie = (res: Response) =>
    decodeURIComponent(res.headers.getSetCookie()[0].match(/h3-test=([^;]+)/)![1]);
  const registerRoute = (path: string, config: SessionConfig) => {
    t.app.all(path, async (event) => {
      const session = await useSession(event, config);
      if (event.req.method === "POST") {
        await session.update((await readBody(event)) as any);
      }
      return { session };
    });
  };

  beforeEach(() => {
    registerRoute("/extra", extraConfig);
    registerRoute("/plain", sessionConfig);
  });

  it("unseals a session sealed with an extra password, from the cookie and the header", async () => {
    const sealed = await sealedWith(previousPassword, { user: "alice" });

    const fromCookie = await t.fetch("/extra", { headers: { Cookie: `h3-test=${sealed}` } });
    expect(await fromCookie.json()).toMatchObject({
      session: { id: "old", createdAt, data: { user: "alice" } },
    });

    const fromHeader = await t.fetch("/extra", { headers: { "x-h3-test-session": sealed } });
    expect(await fromHeader.json()).toMatchObject({
      session: { id: "old", createdAt, data: { user: "alice" } },
    });
  });

  it("discards sessions sealed with a password outside both lists", async () => {
    const sealed = await sealedWith(strangerPassword, { user: "mallory" });
    const res = await t.fetch("/extra", { headers: { Cookie: `h3-test=${sealed}` } });
    const body = await res.json();
    expect(res.status).toBe(200);
    expect(body.session.id).not.toBe("old");
    expect(body.session.data).toEqual({});
  });

  it("keeps the current behavior when no extra passwords are configured", async () => {
    registerRoute("/empty", { ...sessionConfig, extraUnsealPasswords: [] });
    const sealed = await sealedWith(previousPassword, { user: "alice" });
    for (const path of ["/plain", "/empty"]) {
      const res = await t.fetch(path, { headers: { Cookie: `h3-test=${sealed}` } });
      expect(res.status).toBe(200);
      const body = await res.json();
      expect(body.session.id).not.toBe("old");
      expect(body.session.data).toEqual({});
    }
  });

  it("seals with the current password only", async () => {
    const res = await t.fetch("/extra", { method: "POST", body: JSON.stringify({ user: "bob" }) });
    const sealed = resealedCookie(res);
    await expect(unseal(sealed, previousPassword, sealDefaults)).rejects.toThrow();
    expect(await unseal(sealed, sessionConfig.password, sealDefaults)).toMatchObject({
      data: { user: "bob" },
    });
  });

  it("unseals and reseals legacy sessions sealed with an extra password", async () => {
    const legacySealed = await seal(
      { id: "legacy", createdAt, data: { user: "legacy" } },
      previousPassword,
      legacySealOptions,
    );
    const res = await t.fetch("/extra", { headers: { Cookie: `h3-test=${legacySealed}` } });
    expect(await res.json()).toMatchObject({
      session: { id: "legacy", data: { user: "legacy" } },
    });
    expect(res.headers.getSetCookie()).toHaveLength(1);
    expect(await unseal(resealedCookie(res), sessionConfig.password, sealDefaults)).toMatchObject(
      { id: "legacy" },
    );
  });

  it("rejects legacy sessions sealed with an extra password with legacySealFallback: false", async () => {
    registerRoute("/extra-strict", { ...extraConfig, legacySealFallback: false });
    const legacySealed = await seal(
      { id: "legacy", createdAt, data: { user: "legacy" } },
      previousPassword,
      legacySealOptions,
    );
    const res = await t.fetch("/extra-strict", {
      headers: { Cookie: `h3-test=${legacySealed}` },
    });
    const body = await res.json();
    expect(body.session.id).not.toBe("legacy");
    expect(body.session.data).toEqual({});
  });

  it("reseals a cookie session opened by an extra password with the current password", async () => {
    const sealed = await sealedWith(previousPassword, { user: "alice" });
    const res = await t.fetch("/extra", { headers: { Cookie: `h3-test=${sealed}` } });
    expect(res.headers.getSetCookie()).toHaveLength(1);
    const resealed = resealedCookie(res);
    await expect(unseal(resealed, previousPassword, sealDefaults)).rejects.toThrow();

    // The next request only needs the current password
    const next = await t.fetch("/plain", { headers: { Cookie: `h3-test=${resealed}` } });
    expect(await next.json()).toMatchObject({
      session: { id: "old", data: { user: "alice" } },
    });
  });

  it("does not reseal a session opened by an extra password from the header", async () => {
    const sealed = await sealedWith(previousPassword, { user: "alice" });
    const res = await t.fetch("/extra", { headers: { "x-h3-test-session": sealed } });
    expect(await res.json()).toMatchObject({ session: { id: "old", data: { user: "alice" } } });
    expect(res.headers.getSetCookie()).toHaveLength(0);
  });

  it("emits one Set-Cookie when legacy, extra password and idle sliding all apply", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      registerRoute("/combo", {
        name: "h3-combo",
        password: sessionConfig.password,
        extraUnsealPasswords: [previousPassword],
        idleTimeout: 60,
      });
      const sealed = await seal(
        { id: "combo", createdAt: t0, data: {} },
        previousPassword,
        legacySealOptions,
      );
      // 45s in: past half the idle window, so reading slides it
      vi.setSystemTime(t0 + 45_000);
      const res = await t.fetch("/combo", { headers: { Cookie: `h3-combo=${sealed}` } });
      expect(await res.json()).toMatchObject({ session: { id: "combo" } });
      expect(res.headers.getSetCookie()).toHaveLength(1);
    } finally {
      vi.useRealTimers();
    }
  });

  it("expires sessions opened by an extra password at maxAge", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      registerRoute("/extra-max", {
        name: "h3-extra-max",
        password: sessionConfig.password,
        extraUnsealPasswords: [previousPassword],
        maxAge: 60,
      });
      const sealed = await seal(
        { id: "max", createdAt: t0, data: {} },
        previousPassword,
        sealDefaults,
      );
      const cookie = `h3-extra-max=${sealed}`;

      vi.setSystemTime(t0 + 59_000);
      const res1 = await t.fetch("/extra-max", { headers: { Cookie: cookie } });
      expect((await res1.json()).session.id).toBe("max");

      vi.setSystemTime(t0 + 61_000);
      const res2 = await t.fetch("/extra-max", { headers: { Cookie: cookie } });
      expect((await res2.json()).session.id).not.toBe("max");
    } finally {
      vi.useRealTimers();
    }
  });

  it("expires sessions opened by an extra password after idleTimeout without a reseal", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      registerRoute("/extra-idle", {
        name: "h3-extra-idle",
        password: sessionConfig.password,
        extraUnsealPasswords: [previousPassword],
        idleTimeout: 60,
      });
      const sealed = await seal(
        { id: "idle", createdAt: t0, data: {} },
        previousPassword,
        sealDefaults,
      );
      vi.setSystemTime(t0 + 61_000);
      const res = await t.fetch("/extra-idle", {
        headers: { Cookie: `h3-extra-idle=${sealed}` },
      });
      expect((await res.json()).session.id).not.toBe("idle");
    } finally {
      vi.useRealTimers();
    }
  });

  it("rejects invalid extraUnsealPasswords before reading the cookie", async () => {
    const errors: unknown[] = [];
    let config = extraConfig;
    t.app.get("/validate", async (event) => {
      for (const read of [getSession, useSession]) {
        await read(event, config).catch((error) => errors.push(error));
      }
      return "ok";
    });
    // A valid cookie, so a failure can only come from the config check
    const cookie = `h3-test=${await sealedWith(previousPassword, { user: "alice" })}`;

    const invalid: Array<{ value: unknown; override: Record<string, unknown> }> = [
      { value: "", override: { extraUnsealPasswords: [""] } },
      { value: "too-short", override: { extraUnsealPasswords: ["too-short"] } },
      { value: 123, override: { extraUnsealPasswords: [123] } },
      { value: "not-an-array", override: { extraUnsealPasswords: "not-an-array" } },
    ];
    for (const { value, override } of invalid) {
      config = { ...sessionConfig, ...override } as SessionConfig;
      errors.length = 0;
      const res = await t.fetch("/validate", { headers: { Cookie: cookie } });
      expect(res.status).toBe(200);
      expect(errors).toHaveLength(2);
      for (const error of errors) {
        expect(error).toBeInstanceOf(Error);
        const message = (error as Error).message;
        expect(message).toContain("extraUnsealPasswords");
        if (typeof value === "string" && value) {
          expect(message).not.toContain(value);
        }
      }
    }
  });

  it("does not try extra passwords for a malformed or expired cookie", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
    try {
      const expired = await seal({ id: "x", createdAt: t0, data: {} }, previousPassword, {
        ...sealDefaults,
        ttl: 1000,
      });
      vi.setSystemTime(t0 + 3_600_000);

      const countDerivations = async (path: string, cookie: string) => {
        deriveBits.mockClear();
        await t.fetch(path, { headers: { Cookie: `h3-test=${cookie}` } });
