import { defaults as sealDefaults, unseal } from "./iron-crypto.ts";
import type { SealOptions } from "./iron-crypto.ts";
import type { Session, SessionConfig } from "../session.ts";

export const kGetSession: unique symbol = /* @__PURE__ */ Symbol.for("h3.internal.session.promise");

export const kSessionNew: unique symbol = /* @__PURE__ */ Symbol.for("h3.internal.session.new");

export const kLegacySeal: unique symbol = /* @__PURE__ */ Symbol.for(
  "h3.internal.session.legacy-seal",
);

export const kStaleSeal: unique symbol = /* @__PURE__ */ Symbol.for(
  "h3.internal.session.stale-seal",
);

export const DEFAULT_SESSION_NAME = "h3";

export const DEFAULT_SESSION_COOKIE: SessionConfig["cookie"] = {
  path: "/",
  secure: true,
  httpOnly: true,
  sameSite: "lax",
};

